// Generated by tools/import_d2r_helmet_art.py - keep base names in sync with D2R armor.txt.
// Helmet GLBs and 256px albedo maps live in assets/d2survivors/models/helmets.

export type D2HelmetVisualId =
  | "cap"
  | "jawbone"
  | "skull"
  | "helm"
  | "full"
  | "great"
  | "bone"
  | "crown"
  | "circlet"
  | "coronet"
  | "diadem"
  | "tiara"
  | "mask"
  | "assault"
  | "avenger"
  | "fanged"
  | "horned"
  | "wolf"
  | "hawk"
  | "antlers"
  | "falcon"
  | "spirit";

export interface D2HelmetVisual {
  id: D2HelmetVisualId;
  model: string;
  texture: string;
  /** Head-bone local scale; all D2R helmet meshes share one authoring scale. */
  scale: number;
  /** Head-bone local lift, used to seat hats on the skull rather than the jaw. */
  lift: number;
  /** Which of the rig's built-in hair layers belongs under this piece. */
  hair: "none" | "half" | "full";
  /** Extra head-local rotation for source meshes authored on another axis. */
  rotation?: [number, number, number];
  /**
   * Skip the skull-envelope clamp. Pieces whose horns or crest inflate the mesh
   * bounds would otherwise be shrunk by a bound the shell itself never reaches.
   */
  noFit?: boolean;
  metalness: number;
  roughness: number;
}

const HELMET_ROOT = "assets/d2survivors/models/helmets";

function helmet(
  id: D2HelmetVisualId,
  hair: D2HelmetVisual["hair"],
  lift = 0.0012,
  metalness = 0.12,
  roughness = 0.78,
  rotation: [number, number, number] = [0, 0, 0],
): D2HelmetVisual {
  return {
    id,
    model: `${HELMET_ROOT}/${id}.glb`,
    texture: `${HELMET_ROOT}/${id}.png`,
    scale: 0.00305,
    lift,
    hair,
    rotation,
    metalness,
    roughness,
  };
}

//
// Lifts seat the mesh on the *skull*, and the seat every human piece below was
// authored against sat about one brow too low: mounting each mesh on the seven
// class rigs and rendering it showed the cap's face opening, the skull/helm/full
// brow, the fanged and jawbone plates and the mask and bone eye holes all cutting
// across the eyes, and every circlet, coronet, tiara, diadem, crown and horned
// band riding the eye line instead of the forehead. The whole family shared the
// same offset, so the seat moved up by one brow (0.0003 head-local, ~1 unit on a
// 9-unit head) rather than per piece. The beast masks (wolf, hawk, antlers,
// falcon, spirit) keep 0.0009: their eye holes already line up with the eyes, and
// the Avenger Guard and great helm keep their own corrections below.
export const D2_HELMET_VISUALS: Record<D2HelmetVisualId, D2HelmetVisual> = {
  // Low caps need the close-cropped full-helm hair layer. The half-helm layer
  // is longer than the cap shell and clips through it, especially on the paladin.
  cap: helmet("cap", "full", 0.0012, 0.02, 0.88),
  jawbone: helmet("jawbone", "half", 0.0013, 0.02, 0.86),
  skull: helmet("skull", "full", 0.0012, 0.05, 0.8),
  helm: helmet("helm", "half", 0.0012, 0.55, 0.48),
  full: helmet("full", "full", 0.0012, 0.6, 0.46),
  great: helmet("great", "full", 0.0012, 0.6, 0.44),
  bone: helmet("bone", "full", 0.0012, 0.08, 0.78),
  crown: helmet("crown", "none", 0.0012, 0.65, 0.38),
  circlet: helmet("circlet", "none", 0.0011, 0.6, 0.42),
  coronet: helmet("coronet", "none", 0.0011, 0.6, 0.42),
  diadem: helmet("diadem", "none", 0.00115, 0.6, 0.42),
  tiara: helmet("tiara", "none", 0.0011, 0.6, 0.42),
  mask: helmet("mask", "full", 0.0012, 0.1, 0.76),
  assault: helmet("assault", "full", 0.0012, 0.6, 0.5),
  avenger: helmet("avenger", "full", 0.0018, 0.6, 0.5),
  fanged: helmet("fanged", "full", 0.0012, 0.55, 0.52),
  horned: helmet("horned", "full", 0.0012, 0.58, 0.5),
  wolf: helmet("wolf", "full", 0.0009, 0.02, 0.9),
  hawk: helmet("hawk", "full", 0.0009, 0.02, 0.9),
  antlers: helmet("antlers", "full", 0.0009, 0.02, 0.9),
  falcon: helmet("falcon", "full", 0.0009, 0.02, 0.9),
  spirit: helmet("spirit", "full", 0.0009, 0.02, 0.9),
};

/**
 * The great helm's bowl (y -0.21..0.29 in the rip) measures 0.36 units wide
 * against 0.75-0.95 for the helmets that seat on the skull, so at the shared
 * scale the bowl sank inside the head and only its crest poked out. Doubling it
 * puts the bowl back around the skull. The crest above the bowl runs on to
 * y 1.0, which drags the mesh bounds centre up to y 0.39: the mount seats the
 * *bounds* centre, so at the shared lift the bowl landed half a head below the
 * skull, centred on the chin. The lift below adds back that offset
 * (0.39 - 0.04 bowl centre = 0.35 units * 0.0061 = 0.0021) plus the head bone's
 * own skull offset. Its crest also inflates the mesh bounds, so the piece opts
 * out of the skull-envelope clamp, which would otherwise shrink it straight
 * back down.
 *
 * Lifts are authored at a head fit of 1 and the mount now scales them by each
 * class's own fit (see helmetSeatOffset), because a bare head-local lift moved
 * this bowl by 3104 units of head on the druid and 4181 on the sorceress: it
 * rode ~30% high on the sorceress while sitting right on the druid.  At 0.003
 * the druid, amazon and paladin seats stay where they looked right and the
 * sorceress and assassin drop back onto the skull with them.
 */
D2_HELMET_VISUALS.great = { ...D2_HELMET_VISUALS.great, scale: 0.0061, lift: 0.003, noFit: true };

/**
 * The Avenger Guard's rip carries tall wings that drag both the mesh bounds and
 * the bounds centre upwards, so the bowl was seated below the barbarian's crown
 * and the top of the skull showed over its rim. Its bowl is also only 0.71 units
 * wide against a 0.00243 model-unit skull, so the temples stuck out of the sides.
 * Seat it higher, widen it past the skull, and skip the envelope clamp: that
 * clamp measures the wings, not the bowl, and would shrink the fix away.
 */
D2_HELMET_VISUALS.avenger = {
  ...D2_HELMET_VISUALS.avenger,
  scale: 0.00335,
  // 0.0018 at the barbarian's 0.887 * 1.05 = 0.931 head fit, divided back out
  // like the great helm so the mount can scale it per class.
  lift: 0.00193,
  noFit: true,
};

